-- step: new
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'website-governance-plan','Website Governance Plan','One home for governance (Oct 28 huddle): the Website Governance Plan, the new plan being implemented, the conversation with Dr. Fleming and school leadership, school WCM certification enforcement, the internal web steering committee and AI liaisons and school marketing. Merged here: School WCM Certification Assessment, Internal Web Steering Committee, AI Liaisons & School Marketing, Website Standards and Leadership Support. Vanessa reviews the updated governance document Sean sent.','Sean A. Russell',array['Vanessa','Tricia','Farrah']::text[],'in-progress',true,true,'high','Oct 28 District Web Team Huddle',now(),now(),'https://bcpsmarcomm.com/playbooks/bcps-website-governance-plan-2026-06-10' where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='website-governance-plan');
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'school-data-sheet','School Data Sheet','One spreadsheet that fills every school profile in BCPS MarComm (Oct 28 huddle): the BCPS Central list (certification data) plus page links per school (homepage, School Choice and magnet landing pages) and logos. Bulk updates by sheet, small edits in the profile. Sean and Vanessa meet Friday, Oct 30 to settle the columns. Merged here: SharePoint Master List - School Logos.','Vanessa',array['Sean A. Russell','Andrea']::text[],'in-progress',false,true,'high','Oct 28 District Web Team Huddle',now(),now(),null where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='school-data-sheet');
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'pilot-schools','Pilot Schools','Each school lead picks about three responsive schools to test new tools before they go to every school (Oct 28 huddle): the school ADA scan and audit, the school WCM view, Banner Submission and Pride Points. School leads chose their schools at their Oct 28 team meeting. Sean sets up a view so leads can see the WCM experience.','Vanessa',array['Rudy','Nakesha','Andrea']::text[],'in-progress',false,true,'high','Oct 28 District Web Team Huddle',now(),now(),null where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='pilot-schools');
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'heading-sizes','Heading Sizes and Heading Order','WCMs skip heading levels (H1 to H3) because they like the smaller size (Oct 27 Hot Lab, Oct 28 huddle). Proposal: smaller sizes site-wide (for example H1 22 to 20, H2 18 to 16) so the right level also looks right; a site-wide commitment, to decide as a team. Also a short heading guide for WCMs (what H2 to H5 are for), linked from the course and the audit.','Sean A. Russell',array['Vanessa']::text[],'in-progress',true,true,'medium','Oct 28 District Web Team Huddle',now(),now(),null where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='heading-sizes');
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'ai-website-platform-conversation','AI for the Website Platform','After the last meeting, a request came in to escalate conversations about using AI for the website platform; Sean replied this week (Oct 28 huddle). Tricia joins because she oversees the RFP process. No meetings set yet.','Sean A. Russell',array['Tricia']::text[],'in-progress',true,false,'medium','Oct 28 District Web Team Huddle',now(),now(),null where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='ai-website-platform-conversation');
insert into public.bcps_assignment_tags (assignment_slug,title_override,description_override,lead_override,support_override,status,team_ooc,team_app_services,priority,added_from_meeting,added_at,updated_at,playbook_url) select 'wcm-tooltip-request','Hover Tooltips for a Training List (Vince Watson)','Oct 29 Hot Lab: Vince Watson was asked for a page where hovering over a training shows its description. Check whether Finalsite supports it natively; if not, build it as a widget. Vince builds it with current tools first, then books 30 minutes with the requester and an example if more is needed.','Sean A. Russell',null,'in-progress',true,false,'low','Oct 28 District Web Team Huddle',now(),now(),null where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='wcm-tooltip-request');

-- step: update
update public.bcps_assignment_tags set updated_at=now(), title_override='WCM and Director Updates', description_override='Update emails to Department WCMs and directors, and director access to BCPS MarComm (Oct 28 huddle: combined). WCM update email and director email drafted Oct 29 from the Oct 27 and Oct 29 Hot Labs and the Oct 28 huddle; Sean sends from Outlook while ISD grants access for the automatic weekly emails. Directors are invited in stages. Merged here: WCM Update Email (Audits, Analytics, Certification) and Director Sign-In View.' where assignment_slug='director-updates-and-bcps-marcomm-portal-access';
update public.bcps_assignment_tags set updated_at=now(), description_override='Department website audits and the division review windows (Oct 1 to Dec 18: HR, Student Services, Academics, Chief of Staff). Audits run from the WCM dashboard and WCMs are using them. Open: a formal how-to guide for running the audit; page ownership fixes (see Department Audit Page Ownership); the single-column check flags side-by-side sections such as Important Links (Oct 29 Hot Lab: allow them, re-run next week); Finalsite-owned items showing on WCM lists again (filter them out). Merged here: Department Audit Rebuild.' where assignment_slug='wcm-audits-departments';
update public.bcps_assignment_tags set updated_at=now(), title_override='Department & Program Directory Widget', description_override='One search across every department page and program, A to Z, with plain-language tags (live in the Widgets hub). On the back burner until the newsroom project is done, then rolled out (Oct 28 huddle). Merged here: Departments and Programs & Services Directory.' where assignment_slug='widget-program-directory';
update public.bcps_assignment_tags set updated_at=now(), description_override='2026-27 school website audits in BCPS Central (Vanessa, Oct 28 huddle): WCMs get access as they finish the course; the audit is due Dec 1 and the media center update Dec 18. Submission numbers come to the next huddle (Vanessa, Nakesha). Team leads review a component only when it reads Waiting for District Approval. Merged here: WCM Audits - Schools 2026-27.' where assignment_slug='wcm-audits-schools';
update public.bcps_assignment_tags set updated_at=now(), title_override='Department WCM Certification', description_override='Department WCM certification, due Oct 30. Course stays open through the weekend; end-of-day Monday, Nov 2 check: 95% and up get a personal follow-up, low or not started get a segmented message. Removals from Nov 2 with case-by-case extensions for new WCMs. LAB course completion for certified WCMs (raised by Patricia Sapp) and the public /lab link for new WCMs. Merged here: LAB Course Completion.' where assignment_slug='canvas-course-departments';
update public.bcps_assignment_tags set updated_at=now(), description_override='Ongoing BCPS MarComm changes from Hot Lab feedback. Open: double department header on the dashboard after the Dashboard button change (Patricia Sapp, Oct 29 Hot Lab). Merged here and still to confirm: feedback button with type, dictate or record; member notification bell and inbox; certification complete page updates; Hot Lab notes access sweep for new WCMs.' where assignment_slug='wcm-dept-marcom-platform';
update public.bcps_assignment_tags set updated_at=now(), title_override='Tracker Improvements', description_override='Make the tracker faster to review (Oct 28 huddle): consolidate duplicates (done Oct 29), credit each note to the person who gave the update, recording on Add your input, notes on any row, and a reminder 48 hours before a deadline by the bell and email (Vanessa). Transcript upload: status dropdown cut off and no progress indicator still open. Everyone reviews their rows and adds updates before the huddle (Tricia).' where assignment_slug='tracker-transcript-upload';
update public.bcps_assignment_tags set updated_at=now(), title_override='Department Audit Page Ownership', description_override='Pages showing in the wrong department audit. Home School Education (Deanna Greist) still shows Magnet & Innovative Programs pages (Allan Llanos). Early Childhood Education (Jennifer Amador, Oct 29 Hot Lab): Welcome to Kindergarten belongs to Elementary Education (Jamie Ferguson); owner of Employee Early Childhood Education Opportunities still to find. WCMs are asked to check their audit lists only their pages.' where assignment_slug='home-school-education-audit-split';
update public.bcps_assignment_tags set updated_at=now(), title_override='Shared Content Inventory and Guide', description_override='Inventory of department content shared on school websites (whole pages, containers, elements) so departments know what they share and keep it current (Vanessa, Oct 28 huddle; example: the new anti-bullying page was not reported, so school sites kept linking to the old one). Start from the elementary, middle and high standards in the Community Hub. Felicia and Andrea lead, Vanessa supports. Also the guide for Department WCMs on shared elements.', lead_override='Felicia', support_override=array['Andrea','Vanessa']::text[] where assignment_slug='shared-elements-guide';
update public.bcps_assignment_tags set updated_at=now(), title_override='BCPS Platform Ownership Migration', playbook_url='https://bcpsmarcomm.com/playbooks/bcps-platform-ownership-migration' where assignment_slug='district-owned-platform-and-ai-tooling-plan';
update public.bcps_assignment_tags set updated_at=now(), description_override='Resolved Oct 29: Thomas Dusch is the Emergency Management WCM and is completing certification; Marianne Howard is covered in the director email. Emergency Management pages are off the Safety & Security Operations audit.', status='completed', completed_at=now() where assignment_slug='emergency-management-wcm-assignment';
update public.bcps_assignment_tags set updated_at=now(), description_override='Requested Sept 22 by Lindsey Way (VPK Program Specialist). The updated spreadsheet with age symbols came from Lindsey on Oct 8 (Re: EHS/HSP/VPK/Pre-K School List); Sean thought he was still waiting on it. Build the draft and share it with Lindsey Way and Jennifer Amador (Oct 29 Hot Lab).' where assignment_slug='widget-ece-school-search';
update public.bcps_assignment_tags set updated_at=now(), description_override='Allan Llanos (Oct 27 Hot Lab) asked for a countdown to event dates on landing pages: BCPS Showcase Dec 1 and the magnet event. Marketing was not sure it adds much (Oct 28 huddle); the real question is what Magnet wants to achieve. Meeting with Allan Oct 30, 10:30 AM, where Sean also shows the Magnet Program Explorer.' where assignment_slug='event-countdown-widget';
update public.bcps_assignment_tags set updated_at=now(), description_override='Magnet Program Explorer is live (Oct 27): browse by school or program, map of 48 magnet schools, school and program pages, directions. Next (Oct 28 huddle): school logos from Graphics and program icons, a School Choice menu that appears only while School Choice is open, school demographics. Show Allan Llanos on Oct 30.' where assignment_slug='widget-magnet-explore';
update public.bcps_assignment_tags set updated_at=now(), description_override='Vince Watson canceled the Oct 29 2 PM and will rebook. Lilia E. Durham: walked through her audit at the Oct 27 and Oct 29 Hot Labs (two-column check, out-of-date dates on the Metal Detector Program page). Marcia Dixon (97% certified) messages Sean on Teams if blocked.' where assignment_slug='wcm-one-on-one-sessions-vince-watson-lilia-e-durham';
update public.bcps_assignment_tags set updated_at=now(), description_override='Banner Submission tool. Large uploads are now compressed automatically (Logan); Vanessa reviews it once more (Oct 28 huddle). Only two or three of the seven pilot WCMs gave feedback, so the pilot moves to the Pilot Schools group.' where assignment_slug='automate-rejected-banners';
update public.bcps_assignment_tags set updated_at=now(), description_override='Parent portal prototype built in BCPS MarComm and shared with Farrah (no major notes); one more round, then the same template for students and community, with a quarterly check-in to departments that own sections. Phase two: a school version for the Parents & Families landing page (Vanessa). On hold while the newsroom project runs; Finalsite cannot create new newsroom categories and is looking into it (Oct 28 huddle).' where assignment_slug='portal-pages-refresh';
update public.bcps_assignment_tags set updated_at=now(), description_override='Filed Oct 28: every audit check, who fixes it (WCM, Finalsite or the District Web Team), fix steps and live failure counts, with six decisions. The whole team reviews it, since schools will use the same audit (Oct 28 huddle); then a WCM version goes out. Escalation path for WCMs ends with a message to their district web lead; common questions become linked answers.' where assignment_slug='audit-error-guide-district-web-team-decisions';
update public.bcps_assignment_tags set updated_at=now(), description_override='Next quarterly: deeper look at audits, telling your story, a video production pilot and a PDF scan-and-fix tool (Oct 29 Hot Lab). Breakout rooms by school lead, pre-assigned by a second organizer (Tricia, Oct 28 huddle). Plan locked by the next huddle.' where assignment_slug='wcm-quarterly-meetings';

